def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]

    # Width of the framed pattern area, including its right border.
    border = 0
    while border < w and grid[0][border] == frame:
        border += 1

    separators = [
        r for r in range(h)
        if all(grid[r][c] == frame for c in range(border))
    ]
    panels = list(zip(separators, separators[1:]))

    out = [row[:border] for row in grid]

    # Collect each colored object's shape, normalized to its top-left.
    objects = {}
    for color in set(v for row in grid for v in row):
        if color == 0 or color == frame:
            continue
        cells = {
            (r, c)
            for r in range(h)
            for c in range(border + 1, w)
            if grid[r][c] == color
        }
        if cells:
            minr = min(r for r, c in cells)
            minc = min(c for r, c in cells)
            objects[color] = {
                (r - minr, c - minc) for r, c in cells
            }

    for top, bottom in panels:
        # Zeros in the panel's interior form the shape to be copied.
        zeros = [
            (r, c)
            for r in range(top + 1, bottom)
            for c in range(1, border - 1)
            if grid[r][c] == 0
        ]
        if not zeros:
            continue

        minr = min(r for r, c in zeros)
        minc = min(c for r, c in zeros)
        shape = {(r - minr, c - minc) for r, c in zeros}

        color = next(
            (col for col, obj_shape in objects.items() if obj_shape == shape),
            None
        )
        if color is not None:
            for r, c in zeros:
                out[r][c] = color

    return out
